function contact(){return `${pageHero('Contact & consultation','Tell us what you are working on.','We welcome enquiries from students, doctoral researchers, academic teams and independent scholars. Describe your project and we can discuss a suitable service.')}<section class="section section-light" id="enquiry"><div class="container contact-wrap"><aside class="contact-box"><span class="eyebrow" style="color:#a8e1d7">Get in touch</span><h3>Start with a conversation.</h3><p>Share a brief overview of your research challenge. We will review the request and respond through the available contact channel.</p><div class="contact-item"><small>Email</small><br><a href="mailto:${EMAIL}">${EMAIL}</a></div><div class="contact-item"><small>WhatsApp</small><br><a href="${WA}" target="_blank" rel="noopener noreferrer">${PHONE} ↗</a></div><div class="contact-item"><small>Consultation</small><br>By prior arrangement, online</div><p style="font-size:13px;margin-top:26px">Please note: no time slot is confirmed until we respond.</p></aside>${form()}</div></section>${chinaContactSection()}`}
function integrity(){return `${pageHero('Our principles','Research integrity is non-negotiable.','We believe academic support should improve independent research practice, not substitute for it.')}<section class="section section-light"><div class="container legal"><h2>What we support</h2><p>Research planning, methods consultation, survey design guidance, statistical interpretation, literature-review methods, language and structural editing, and feedback that helps researchers make their own scholarly decisions.</p><h2>What we do not offer</h2><p>We do not offer ghostwriting for assessed work, fabrication or manipulation of data, false authorship, paid acceptance arrangements, fake peer reviews or guaranteed journal publication.</p><h2>What our research stages mean</h2><p><strong>Submitted manuscript / editorial review:</strong> submitted for editorial consideration; this does not imply acceptance, completed peer review or publication.</p><p><strong>Advanced manuscript draft:</strong> a substantial working manuscript that is still being refined. It is not presented as a submitted or published paper.</p><p><strong>Developing research:</strong> data, model verification or research design is still in progress. Validated empirical findings are not claimed.</p><p>Stage labels follow the supplied portfolio information. Posters are educational summaries, not the underlying manuscripts or datasets. No numerical findings or third-party endorsements are asserted.</p><h2>Client responsibility</h2><p>Clients remain responsible for the integrity, originality, accuracy, authorship and ethical approvals applicable to their research, and for following their institution's rules and journal policies.</p></div></section>`}
function privacy(){return `${pageHero('Website information','Privacy notice.','How ScholarBridge handles your contact and consultation enquiries.')}<section class="section section-light"><div class="container legal"><p class="pill">Draft for business-owner and legal review · 17 November 2026</p><h2>What this website collects</h2><p>The enquiry form collects your name, email, country, research field, service selection, deadline, project description and consent, together with any optional phone number, organization, research level and consultation preferences you provide. Direct submissions are processed and stored through Netlify Forms, including spam filtering. Email or WhatsApp links open the corresponding application; messages sent there are handled by those providers.</p><h2>How submitted details are used</h2><p>If you send Scholar Bridge an enquiry, the contact details and research description you provide may be used to respond, discuss a potential engagement and retain relevant business correspondence. Do not include sensitive research datasets or confidential documents in the initial enquiry.</p><h2>Cookies, analytics and retention</h2><p>No analytics scripts or advertising cookies are added by this website. Hosting providers may process request logs and security information. A fixed retention schedule has not yet been adopted; the owner should set one and regularly review and delete enquiries no longer needed. This draft does not assert compliance with any particular privacy law.</p><h2>Third-party services</h2><p>This website uses Google Fonts and provides links to WhatsApp and email services. These providers may process technical data under their own policies. Netlify hosts this site and processes direct form submissions and associated technical information. Submitted enquiries are accessible to authorized site administrators. To request access, correction or deletion of your enquiry, contact the email below. Business correspondence is retained as needed to handle the enquiry and meet applicable obligations.</p><h2>Contact</h2><p>For privacy questions, contact <a href="mailto:${EMAIL}">${EMAIL}</a>.</p></div></section>`}
function terms(){return `${pageHero('Website information','Terms of use.','General information about using this website and contacting Scholar Bridge.')}<section class="section section-light"><div class="container legal"><p class="pill">Draft for business-owner and legal review · 17 November 2026</p><h2>Informational purpose</h2><p>Website content is general information about proposed consultancy services and educational research principles. It is not a substitute for project-specific professional advice or institutional regulations.</p><h2>No automatic engagement</h2><p>Submitting an enquiry does not create a consultancy agreement or confirm a consultation. Service scope, fees, deliverables and schedules must be agreed separately.</p><h2>No publication guarantee</h2><p>Journal acceptance, academic assessment outcomes and research findings are determined independently and cannot be guaranteed.</p><h2>Academic integrity</h2><p>Users agree not to seek services that facilitate research misconduct or violate academic assessment requirements.</p><h2>Contact</h2><p>Questions about these terms may be directed to <a href="mailto:${EMAIL}">${EMAIL}</a>.</p></div></section>`}
function initForm(){
  const f=document.getElementById('contact-form');if(!f)return;
  const selected=new URLSearchParams(location.search).get('service');
  if(selected&&[...f.elements.service.options].some(x=>x.value===selected))f.elements.service.value=selected;
  const now=new Date();const today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');f.elements.date.min=today;f.elements.deadline.min=today;
  try{f.elements.timezone.value=Intl.DateTimeFormat().resolvedOptions().timeZone;}catch{}
  const status=document.getElementById('form-result');
  f.addEventListener('submit',async e=>{
    e.preventDefault();if(!f.reportValidity())return;
    if(f.elements.date.value&&f.elements.date.value<today){f.elements.date.setCustomValidity('Choose today or a future date.');f.elements.date.reportValidity();return;}
    const button=f.querySelector('[type="submit"]');button.disabled=true;button.textContent='Sending…';f.setAttribute('aria-busy','true');status.classList.add('visible');status.classList.remove('error');status.textContent='Sending your enquiry…';
    try{const response=await fetch('/__forms.html',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(new FormData(f)).toString()});if(!response.ok)throw new Error('Submission failed');f.reset();status.textContent='Thank you. Your enquiry has been received. Any consultation date is a request; we confirm the time personally by email.';}
    catch{status.classList.add('error');status.textContent='Your enquiry could not be sent. Please try again, or contact us by email or WhatsApp. Your entered details are still here.';}
    finally{button.disabled=false;button.textContent='Send enquiry / consultation request →';f.removeAttribute('aria-busy');}
  });
  f.elements.date.addEventListener('input',()=>f.elements.date.setCustomValidity(''));
  document.getElementById('wa-form').addEventListener('click',()=>{if(!f.reportValidity())return;const v=Object.fromEntries(new FormData(f));const body=`ScholarBridge consultation enquiry\nName: ${v.name}\nEmail: ${v.email}\nService: ${v.service}\nResearch field: ${v.subject||'Not specified'}\nPreferred date/time: ${v.date||'To agree'} ${v.time||''} ${v.timezone||''}\n\n${v.message}`;window.open(`${WA}?text=${encodeURIComponent(body)}`,'_blank','noopener,noreferrer');status.classList.add('visible');status.textContent='WhatsApp opens a draft. Press Send there to deliver your message. This does not submit the website form.';});
}
/* Version 3 extensions preserve the original pages and portfolio. */
const serviceSlugs=['research-methodology','statistical-analysis','questionnaire-development','systematic-literature-review','manuscript-editing','doctoral-mentoring'];
serviceCards=()=>services.map(([n,d,i],j)=>`<article class="card"><span class="number">${i}</span><h3><a href="${serviceSlugs[j]}.html">${n}</a></h3><p>${d}</p><a href="${serviceSlugs[j]}.html">Explore this service ↗</a></article>`).join('');
const detailData=[
['Quantitative, qualitative and mixed-methods research design','Research questions and theoretical frameworks','Sampling, recruitment and ethical-review planning','Qualitative interviews, coding and reflexivity','Mixed-method integration and transparent limitations'],
['SPSS, SmartPLS, R and Python','PLS-SEM and confirmatory factor analysis','Mediation and moderation analysis','Reliability and validity testing','Regression analysis and panel-data econometrics','Fixed-effects and random-effects models','fsQCA and statistical robustness checks','Research charts, tables and transparent interpretation'],
['Scale adaptation with source attribution and permissions','Content validity and expert review','Pilot testing and cognitive interviewing','Survey design, response options and accessibility','Measurement documentation and translation planning'],
['PRISMA 2020 reporting and protocol development','Academic database searching and search strategy development','Inclusion and exclusion criteria','Literature screening and exclusion logs','Research extraction matrices','Bibliometric analysis where appropriate','Thematic synthesis and evidence-based literature reviews'],
['Manuscript structure and formatting','Academic English editing and research argument improvement','Journal selection guidance','Reference checking and citation consistency','Reviewer-response preparation','Tables, figures and submission documentation'],
['Research planning and milestone reviews','Methodology coaching','Statistical interpretation','Research presentation support','Feedback that builds independent doctoral research skills']
];
function brochureLink(){return `<a class="btn btn-outline" href="assets/scholarbridge-brochure.pdf" download>Download business brochure · PDF ↓</a>`}
function detailPage(i){return `${pageHero('Research services',services[i][0],services[i][1])}<section class="section section-light"><div class="container article"><h2>Support shaped around your study.</h2><ul class="feature-list">${detailData[i].map(t=>`<li>${t}</li>`).join('')}</ul><h2>What you can expect</h2><p>After an initial discussion, we propose a written scope, quotation, timeline and deliverables for your approval. Depending on the agreed scope, these may include an annotated review, documented analysis workflow, interpretation session or a methods action plan. Tool and method choices depend on the research question, data quality and available expertise.</p>${i===1?demoAnalysis():i===3?demoReview():''}<h2>Responsible support</h2><p>You retain authorship and responsibility for your work. We do not ghostwrite assessed work, fabricate results or offer purchased authorship. Publication and journal acceptance are never guaranteed.</p><div class="actions"><a class="btn btn-teal" href="contact.html?service=${encodeURIComponent(services[i][0])}#enquiry">Discuss this service →</a><a class="btn btn-outline" href="portfolio.html">Explore methodological examples</a></div><p>Related support: <a href="${serviceSlugs[(i+1)%6]}.html">${services[(i+1)%6][0]}</a></p></div></section>${cta()}`}
function demoAnalysis(){return `<aside class="demo"><span class="eyebrow">Demonstration data only</span><h2>From observations to a clear summary.</h2><p>Six invented values: 2, 3, 4, 4, 5, 6. These illustrate descriptive reporting only; they are unrelated to portfolio studies or client results.</p><div class="table-scroll"><table><caption>Illustrative descriptive output — synthetic data</caption><thead><tr><th scope="col">Measure</th><th scope="col">Demonstration value</th></tr></thead><tbody><tr><th scope="row">Observations</th><td>6</td></tr><tr><th scope="row">Mean</th><td>4.00</td></tr><tr><th scope="row">Sample standard deviation</th><td>1.41</td></tr><tr><th scope="row">Range</th><td>2–6</td></tr></tbody></table></div><div class="demo-bars" role="img" aria-label="Synthetic observations: 2, 3, 4, 4, 5, 6">${[2,3,4,4,5,6].map((n,i)=>`<div><span>Observation ${i+1}</span><b style="--bar:${n/6*100}%">${n}</b></div>`).join('')}</div><p>Real reporting also considers missing data, distribution, assumptions and uncertainty; this example makes no inferential claim.</p></aside>`}
function demoReview(){return `<aside class="demo"><span class="eyebrow">Illustrative workflow · no study counts</span><h2>A traceable review process.</h2><ol class="workflow"><li>Identify records through documented database searches</li><li>Remove duplicate records</li><li>Screen titles and abstracts against eligibility criteria</li><li>Assess full texts and document reasons for exclusion</li><li>Include eligible studies and synthesize evidence</li></ol><p>Simplified PRISMA 2020 workflow; a completed review requires the appropriate full checklist and flow diagram.</p><div class="table-scroll"><table><caption>Sample extraction matrix — fictional teaching row</caption><thead><tr><th>Record</th><th>Design</th><th>Context</th><th>Extraction focus</th><th>Limitations</th></tr></thead><tbody><tr><td>Demonstration A (not a citation)</td><td>Cross-sectional survey</td><td>Hypothetical logistics setting</td><td>Measures, sample and analysis approach</td><td>Self-report; causal inference limited</td></tr></tbody></table></div></aside>`}
function booking(){return `${pageHero('Book consultation','A focused conversation. A practical next step.','Request research, statistical analysis, systematic review, manuscript assessment, doctoral mentoring or general academic consulting.')}<section class="section section-light" id="enquiry"><div class="container contact-wrap"><aside class="contact-box"><span class="eyebrow">By personal arrangement</span><h2>Your time zone matters.</h2><p>Choose a preferred date, time and time zone in the form. We review the request and agree availability, scope and any fee before confirming a meeting.</p><p>No live scheduling service is connected. Submitting this form does not reserve a slot.</p><a href="${WA}">Discuss availability on WhatsApp →</a></aside>${form()}</div></section>`}
function posters(){return `${pageHero('Research posters','Research methods, in view.','Existing illustrative research summaries, with stage disclosures and no numerical findings or underlying manuscript content.')}<section class="section section-light"><div class="container"><p class="showcase-disclaimer">These summaries illustrate research areas; they do not establish ScholarBridge authorship or completed client work. Current research stages require confirmation. Approved poster PDF downloads remain unavailable until rights-holder authorization for public distribution is documented.</p>${projectGallery()}</div></section>`}
function confidence(){return `<section class="section section-soft"><div class="container"><div class="section-header"><div><span class="eyebrow">Why ScholarBridge</span><h2>Clarity at each step.</h2></div><p>Support for PhD researchers, master’s students, faculty, independent researchers and institutions in the UAE and internationally.</p></div><div class="expertise-grid"><div><h3>Transparent deliverables</h3><p>Scope, quotation and timelines agreed before work starts.</p></div><div><h3>Confidential handling</h3><p>Share a non-sensitive summary first. Agree access and document handling before sharing research material.</p></div><div><h3>Independent scholarship</h3><p>Ethical consulting, realistic expectations and no guaranteed publication outcomes.</p></div></div><p><strong>Client testimonials:</strong> No testimonials are published. Verified client feedback may be added with permission.</p>${brochureLink()}</div></section>`}
function team(){return `<section class="section section-soft"><div class="container"><span class="eyebrow">Team & expertise</span><h2>Expertise with transparent profiles.</h2><p>Founder name, verified qualifications, experience, biography, photograph and affiliations: awaiting approved information. No credentials or institutional partnerships are claimed.</p><p>Our consultancy approach covers research methodology, analytical interpretation and scholarly communication. Project-specific capability and availability are confirmed during scope review.</p><h3>International support</h3><p>Based in the United Arab Emirates and open to international enquiries, with time zones agreed personally.</p></div></section>`}
function confidentiality(){return `${pageHero('Policy draft','Research confidentiality.','Draft for business-owner and legal review · 17 November 2026')}<section class="section section-light"><div class="container legal"><h2>Before sharing documents</h2><p>Use the enquiry form for a non-sensitive project summary. Do not upload participant records, passwords or protected manuscripts. File attachments are intentionally unavailable in this public form.</p><h2>Agree handling in writing</h2><p>Before an engagement, agree which documents are necessary, who may access them, a suitable transfer method, retention and deletion arrangements, and any confidentiality agreement. Participant data should be minimized and de-identified where appropriate.</p><h2>Public disclosure and authorship</h2><p>Client material, identifying details and unpublished findings must not be used in marketing or portfolio materials without documented rights-holder permission. Consulting does not confer authorship or permission to publish.</p><h2>Questions and requests</h2><p>Contact <a href="mailto:${EMAIL}">${EMAIL}</a> to discuss confidentiality, access or deletion. Specific obligations and response arrangements must be confirmed in the engagement agreement.</p></div></section>`}
const originalHome=home,originalAbout=about,originalServices=servicePage,originalPortfolio=portfolio;
