portfolio=()=>originalPortfolio().replace(cta(),`<section class="section"><div class="container"><h2>Additional research themes</h2><p>BRICS energy, carbon emissions and economic growth; climate resilience and sustainability; digital transformation; supply-chain management; research analytics and methodology.</p><p>These are research interests, not claims of commissioned work, verified findings or publications.</p></div></section>${cta()}`);
const path=location.pathname.split('/').filter(Boolean).pop()||'index.html';const route=path.includes('.')?path:path+'.html';const routes={'index.html':['Home',home],'about.html':['About',about],'services.html':['Services',servicePage],'portfolio.html':['Research Portfolio',portfolio],'poster-logistics.html':['Climate Pressure, AI-Enabled Capability, and Sustainable Logistics',()=>posterPage('logistics')],'poster-analytics.html':['AI-Enabled Supply Chain Analytics and Sustainable Performance',()=>posterPage('analytics')],'poster-maritime.html':['Digital Connectivity, Maritime Logistics & Food Loss',()=>posterPage('maritime')],'poster-coldchain.html':['AI-Enabled Cold-Chain Resilience & Food Loss',()=>posterPage('coldchain')],'insights.html':['Insights',insights],'faq.html':['FAQ',faqPage],'contact.html':['Contact',contact],'thank-you.html':['Enquiry received',()=>`${pageHero('Enquiry received','Check your submission status.','A successful form submission shows a receipt message on the enquiry page. Visiting this page alone does not verify receipt. Consultation times require personal confirmation.')}<section class="section"><div class="container"><a class="btn btn-teal" href="portfolio.html">Explore the research portfolio →</a></div></section>`],'integrity.html':['Academic Integrity',integrity],'privacy.html':['Privacy',privacy],'terms.html':['Terms',terms],'article-methodology.html':['Research Methodology Guide',()=>article('methodology')],'article-analysis.html':['PLS-SEM Analysis Guide',()=>article('analysis')],'article-reviews.html':['Systematic Literature Review Guide',()=>article('reviews')]};serviceSlugs.forEach((slug,i)=>routes[slug+'.html']=[services[i][0],()=>detailPage(i)]);Object.assign(routes,{'book-consultation.html':['Book Consultation',booking],'posters.html':['Research Posters',posters],'confidentiality.html':['Research Confidentiality',confidentiality]});const entry=routes[route]||routes['index.html'];layout(entry[1](),entry[0]);
